(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.02+t*0.3)*15 + Math.cos(y*0.015-t*0.2)*10;
  const w1y = Math.cos(y*0.02-t*0.25)*15 + Math.sin(x*0.018+t*0.35)*10;
  const w2x = Math.sin((x+w1x)*0.03-t*0.5)*8 + Math.cos((y+w1y)*0.025+t*0.4)*6;
  const w2y = Math.cos((y+w1y)*0.03+t*0.45)*8 + Math.sin((x+w1x)*0.028-t*0.35)*6;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.85],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 1.1],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.9],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 1.05],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.95],
    [80+Math.sin(t*0.65+3)*70, 40+Math.cos(t*0.75)*60, 0.11, 2.1, 0.8],
    [400+Math.cos(t*0.45+1)*60, 200+Math.sin(t*0.85+2)*50, 0.13, 1.6, 1.15],
    [200+Math.sin(t*0.55+4)*110, 220+Math.cos(t*0.65+3)*40, 0.075, 2.4, 0.88]
  ];
  let aS=0, iS=0, a2=0, i2=0;
  for (const [sX,sY,f,sp,w] of src) {
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const a=Math.sin(d*f-t*sp), b=Math.sin(d*f*0.7+t*sp*0.6+1.5);
    aS+=a*w; iS+=b*w;
    a2+=Math.sin(d*f*1.4-t*sp*0.8+0.7)*w;
    i2+=Math.sin(d*f*0.5+t*sp*1.1+2.3)*w;
  }
  const act=aS/9, inh=iS/9, act2=a2/9, inh2=i2/9;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2
    +Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4
    +Math.sin(dist*0.08-ang*2+t*0.9)*0.15;
  const rd1=Math.tanh((act-inh*0.7+bg*0.3+spiral)*2.2);
  const rd2=Math.tanh((act2*0.6-inh2*0.5+act*0.3-inh*0.2)*1.8);
  const coupled=Math.tanh((rd1+rd2*0.4)*1.5+Math.sin(rd1*rd2*3)*0.3);
  const vx=Math.floor(sx/20), vy=Math.floor(sy/20);
  const vorX=vx*20+10+Math.sin(vx*1.7+vy*2.3+t*0.6)*8;
  const vorY=vy*20+10+Math.cos(vx*2.1+vy*1.5+t*0.5)*8;
  const vorD=Math.sqrt((sx-vorX)**2+(sy-vorY)**2);
  const vor=Math.max(0, 1-vorD/14)*Math.sin(vorD*0.5-t*2)*0.35;
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const pulse=0.85+Math.sin(t*0.8)*0.15;
  const blend=(coupled*0.6+cell*0.15+vor*0.15+spiral*0.1)*pulse;
  const v=blend*0.5+0.5;
  const pal=[
    [5,10,45],[12,35,85],[18,75,120],[25,130,145],
    [60,175,155],[140,200,120],[210,195,80],
    [230,155,65],[215,105,75],[185,65,85],
    [120,35,75],[55,18,55],[5,10,45]
  ];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const lum=0.75+Math.sin(coupled*Math.PI)*0.25;
  const edge=Math.abs(coupled)>0.65?1.2:Math.abs(coupled)>0.3?1.05:0.92;
  const shimmer=Math.sin(sx*0.3+sy*0.2+t*4)*0.04+1;
  const m=lum*edge*shimmer;
  return [
    Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*m)|0,
    Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*m)|0,
    Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*m)|0
  ];
}
